import numpy as np

def minmax(x):
    x = np.asarray(x, float)
    return (x - x.min()) / (x.max() - x.min() + 1e-9)

def retrieve(episodes, query_vec, now_h, k=2, w=(1.0, 1.0, 1.0)):
    rec = [0.995 ** (now_h - e["hour"]) for e in episodes]          # decay per hour
    imp = [e["importance"] for e in episodes]                        # 1-10 at write
    rel = [float(np.dot(query_vec, e["vec"])) for e in episodes]     # unit vectors
    score = w[0]*minmax(rec) + w[1]*minmax(imp) + w[2]*minmax(rel)
    top = np.argsort(-score)[:k]
    return [episodes[i] for i in top]

def context(episodes, query_vec, now_h):
    return "\n".join(f"- {e['lesson']}" for e in retrieve(episodes, query_vec, now_h))
